/*
 * Nano Blink — classic blink on the Arduino Nano
 * Uses LED_BUILTIN (D13) and an external LED on D9 with PWM fade
 */

const int extLed = 9;   // PWM pin

void setup() {
  pinMode(LED_BUILTIN, OUTPUT);
  pinMode(extLed, OUTPUT);
  Serial.begin(115200);
  Serial.println("Nano blink started!");
}

void loop() {
  // Blink the built-in LED
  digitalWrite(LED_BUILTIN, HIGH);
  Serial.println("LED ON");
  delay(500);
  digitalWrite(LED_BUILTIN, LOW);
  Serial.println("LED OFF");
  delay(500);

  // Fade the external LED through PWM values
  for (int v = 0; v <= 255; v += 5) {
    analogWrite(extLed, v);
    delay(10);
  }
  for (int v = 255; v >= 0; v -= 5) {
    analogWrite(extLed, v);
    delay(10);
  }
}
